"""
StyleLock AI - Backend Server v48
FIXED: CSS display bug - cutcard was overriding .screen display:none
"""

import os
from fastapi import FastAPI, Request
from fastapi.middleware.cors import CORSMiddleware
from fastapi.responses import HTMLResponse

ANTHROPIC_API_KEY = os.getenv("ANTHROPIC_API_KEY", "")
VMODEL_API_KEY = os.getenv("VMODEL_API_KEY", "")
RAZORPAY_KEY_ID = os.getenv("RAZORPAY_KEY_ID", "")
RAZORPAY_KEY_SECRET = os.getenv("RAZORPAY_KEY_SECRET", "")
REMOVEBG_API_KEY = os.getenv("REMOVEBG_API_KEY", "")
ENABLE_BG_REMOVAL = os.getenv("ENABLE_BG_REMOVAL", "false").lower() == "true"

HERO_LOOKS = {
    "bold": "https://stylelock-production.up.railway.app/static/hairstyle_bold.jpg",
    "clean": "https://stylelock-production.up.railway.app/static/hairstyle_clean.jpg",
    "trending": "https://stylelock-production.up.railway.app/static/hairstyle_trending.jpg"
}

app = FastAPI(title="StyleLock AI v48")

app.add_middleware(CORSMiddleware, allow_origins=["*"], allow_credentials=True, allow_methods=["*"], allow_headers=["*"])

@app.get("/")
async def root():
    return {
        "app": "StyleLock AI",
        "version": "48",
        "status": "running",
        "apis": {
            "anthropic": "configured" if ANTHROPIC_API_KEY else "not configured",
            "vmodel": "configured" if VMODEL_API_KEY else "not configured",
            "razorpay": "configured" if RAZORPAY_KEY_ID else "demo mode",
            "removebg": "configured" if REMOVEBG_API_KEY else "not configured",
            "bg_removal_enabled": ENABLE_BG_REMOVAL
        }
    }

@app.post("/api/create-order")
async def create_razorpay_order():
    if not RAZORPAY_KEY_ID:
        return {"order_id": "demo", "amount": 4900, "currency": "INR", "demo": True}
    import razorpay
    client = razorpay.Client(auth=(RAZORPAY_KEY_ID, RAZORPAY_KEY_SECRET))
    order = client.order.create({"amount": 4900, "currency": "INR", "payment_capture": 1})
    return {"order_id": order["id"], "amount": 4900, "currency": "INR"}

@app.post("/api/analyze")
async def analyze_face(request: Request):
    return {"face_shape": "oval", "recommendations": ["bold", "clean", "trending"]}

@app.post("/api/generate")
async def generate_hairstyle(request: Request):
    data = await request.json()
    return {"image_url": HERO_LOOKS.get(data.get("style", "bold"), HERO_LOOKS["bold"])}

FRONTEND_HTML = """<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no, viewport-fit=cover">
  <meta name="theme-color" content="#1a2f2a">
  <meta name="apple-mobile-web-app-capable" content="yes">
  <title>StyleLock</title>
  <link href="https://fonts.googleapis.com/css2?family=Bebas+Neue&family=Space+Mono:wght@400;700&family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">
  <script src="https://checkout.razorpay.com/v1/checkout.js"></script>
  <style>
    :root { --bg-dark: #1a2f2a; --bg-card: #2a3f3a; --lime: #c8e64a; --cream: #f5f3e8; --text-muted: rgba(245,243,232,0.7); --border-subtle: rgba(245,243,232,0.15); }
    * { box-sizing: border-box; margin: 0; padding: 0; }
    html, body { height: 100%%; width: 100%%; overflow: hidden; position: fixed; }
    body { font-family: "Inter", sans-serif; background: var(--bg-dark); color: var(--cream); }
    
    /* CRITICAL: All screens hidden by default, only .active shows */
    .screen { position: fixed; top: 0; left: 0; width: 100%%; height: 100%%; display: none !important; background: var(--bg-dark); }
    .screen.active { display: block !important; }
    
    input[type="file"] { display: none; }
    
    #screen-home.active { background: url("data:image/jpeg;base64,") center top / cover no-repeat; }
    .home-hotspot { position: absolute; bottom: 10%%; left: 50%%; transform: translateX(-50%%); width: 55%%; max-width: 220px; height: 48px; background: transparent; border: none; cursor: pointer; z-index: 100; }
    
    #screen-upload.active { background: url("data:image/jpeg;base64,") center top / cover no-repeat; }
    .upload-hotspot { position: absolute; bottom: 3%%; left: 50%%; transform: translateX(-50%%); width: 92%%; max-width: 380px; height: 60px; background: transparent; border: none; cursor: pointer; z-index: 100; }
    .upload-frame-hotspot { position: absolute; top: 14%%; left: 50%%; transform: translateX(-50%%); width: 82%%; max-width: 340px; height: 58%%; background: transparent; border: none; cursor: pointer; z-index: 100; }
    .upload-preview-overlay { position: absolute; top: 14%%; left: 50%%; transform: translateX(-50%%); width: 82%%; max-width: 340px; height: 58%%; border-radius: 8px; overflow: hidden; opacity: 0; transition: opacity 0.3s; pointer-events: none; z-index: 90; }
    .upload-preview-overlay.visible { opacity: 1; }
    .upload-preview-overlay img { width: 100%%; height: 100%%; object-fit: cover; }
    
    #screen-loading.active { background: url("data:image/jpeg;base64,") center top / cover no-repeat; }
    .loading-progress-overlay { position: absolute; bottom: 10%%; left: 50%%; transform: translateX(-50%%); width: 72%%; max-width: 290px; }
    .loading-progress-bar { height: 10px; background: #555; border-radius: 5px; overflow: hidden; }
    .loading-progress-fill { height: 100%%; background: var(--lime); border-radius: 5px; width: 0%%; animation: loadProgress 4s ease-out forwards; }
    @keyframes loadProgress { 0%% { width: 0%%; } 100%% { width: 100%%; } }
    
    #screen-results.active { overflow-y: auto; }
    .results-header { padding: 20px 24px; text-align: center; }
    .results-title { font-family: "Bebas Neue", sans-serif; font-size: 36px; color: var(--cream); }
    .results-swiper { display: flex; overflow-x: auto; scroll-snap-type: x mandatory; scrollbar-width: none; }
    .results-swiper::-webkit-scrollbar { display: none; }
    .result-slide { flex: 0 0 100%%; scroll-snap-align: center; padding: 0 24px 24px; display: flex; flex-direction: column; align-items: center; }
    .result-card { width: 100%%; max-width: 340px; background: var(--bg-dark); border-radius: 20px; overflow: hidden; border: 1px solid var(--border-subtle); }
    .result-card-hero { position: relative; width: 100%%; aspect-ratio: 3/4; }
    .result-card-hero img { width: 100%%; height: 100%%; object-fit: cover; }
    .result-look-name { position: absolute; top: 16px; left: 16px; font-family: "Bebas Neue", sans-serif; font-size: 32px; color: var(--cream); text-shadow: 0 2px 8px rgba(0,0,0,0.5); }
    .result-card-info { padding: 20px; }
    .result-specs { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin-bottom: 16px; }
    .result-spec { font-family: "Space Mono", monospace; font-size: 11px; }
    .result-spec-label { color: var(--text-muted); }
    .result-spec-value { color: var(--cream); font-weight: 700; }
    .result-next-btn { width: 100%%; padding: 14px; background: var(--lime); border: none; border-radius: 8px; font-family: "Space Mono", monospace; font-size: 14px; font-weight: 700; color: var(--bg-dark); cursor: pointer; }
    .results-dots { display: flex; justify-content: center; gap: 8px; padding: 16px; }
    .dot { width: 8px; height: 8px; border-radius: 50%%; background: var(--bg-card); }
    .dot.active { background: var(--lime); width: 24px; border-radius: 4px; }
    
    #screen-cutcard.active { padding: 40px 24px; flex-direction: column; align-items: center; overflow-y: auto; }
    .cutcard-title { font-family: "Bebas Neue", sans-serif; font-size: 36px; color: var(--cream); margin-bottom: 24px; }
    .cutcard-container { width: 100%%; max-width: 340px; background: var(--cream); border-radius: 20px; padding: 24px; color: var(--bg-dark); }
    .cutcard-header { display: flex; justify-content: space-between; margin-bottom: 20px; padding-bottom: 16px; border-bottom: 2px solid var(--bg-dark); }
    .cutcard-logo { font-family: "Bebas Neue", sans-serif; font-size: 24px; }
    .cutcard-date { font-family: "Space Mono", monospace; font-size: 12px; }
    .cutcard-look-name { font-family: "Bebas Neue", sans-serif; font-size: 42px; margin-bottom: 20px; }
    .cutcard-specs { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; margin-bottom: 24px; }
    .cutcard-spec { font-family: "Space Mono", monospace; font-size: 12px; }
    .cutcard-spec-label { color: var(--bg-card); margin-bottom: 4px; }
    .cutcard-spec-value { font-weight: 700; font-size: 14px; }
    .cutcard-barber-btn { width: 100%%; padding: 16px; background: var(--bg-dark); border: none; border-radius: 8px; font-family: "Space Mono", monospace; font-size: 14px; font-weight: 700; color: var(--lime); cursor: pointer; }
    
    #screen-barber.active { padding: 40px 24px; overflow-y: auto; }
    .barber-header { display: flex; justify-content: space-between; margin-bottom: 24px; }
    .barber-title { font-family: "Bebas Neue", sans-serif; font-size: 28px; color: var(--cream); }
    .barber-close { width: 40px; height: 40px; background: var(--bg-card); border: none; border-radius: 50%%; color: var(--cream); font-size: 20px; cursor: pointer; }
    .barber-image-container { width: 100%%; aspect-ratio: 3/4; background: var(--bg-card); border-radius: 16px; overflow: hidden; margin-bottom: 24px; }
    .barber-image-container img { width: 100%%; height: 100%%; object-fit: cover; }
    .barber-specs-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin-bottom: 24px; }
    .barber-spec-card { background: var(--bg-card); border-radius: 12px; padding: 16px; }
    .barber-spec-label { font-family: "Space Mono", monospace; font-size: 10px; color: var(--text-muted); margin-bottom: 6px; }
    .barber-spec-value { font-family: "Bebas Neue", sans-serif; font-size: 24px; color: var(--lime); }
    .barber-footer { display: flex; justify-content: center; padding-top: 24px; border-top: 1px solid var(--border-subtle); }
    .barber-logo-text { font-family: "Space Mono", monospace; font-size: 14px; color: var(--lime); }
  </style>
</head>
<body>
  <div id="screen-home" class="screen active"><button class="home-hotspot" id="home-unlock-btn"></button></div>
  <div id="screen-upload" class="screen">
    <button class="upload-frame-hotspot" id="upload-frame-btn"></button>
    <div class="upload-preview-overlay" id="upload-preview-container"><img id="upload-preview" src="" alt=""></div>
    <button class="upload-hotspot" id="upload-take-btn"></button>
    <input type="file" id="camera-input" accept="image/*" capture="user">
  </div>
  <div id="screen-loading" class="screen"><div class="loading-progress-overlay"><div class="loading-progress-bar"><div class="loading-progress-fill" id="progress-fill"></div></div></div></div>
  <div id="screen-results" class="screen">
    <div class="results-header"><div class="results-title">YOUR 3 LOOKS</div></div>
    <div class="results-swiper" id="results-swiper"></div>
    <div class="results-dots" id="results-dots"></div>
  </div>
  <div id="screen-cutcard" class="screen">
    <div class="cutcard-title">YOUR CUT CARD</div>
    <div class="cutcard-container" id="cutcard-content"></div>
  </div>
  <div id="screen-barber" class="screen">
    <div class="barber-header"><div class="barber-title">BARBER MODE</div><button class="barber-close" id="barber-close">✕</button></div>
    <div id="barber-content"></div>
  </div>
  <script>
    let currentLooks=[],selectedLook=null;
    const HERO_LOOKS={bold:{name:"BOLD",image:"https://stylelock-production.up.railway.app/static/hairstyle_bold.jpg",top_length:"3 inches",sides:"0.5 fade",texture:"textured",products:"matte clay"},clean:{name:"CLEAN",image:"https://stylelock-production.up.railway.app/static/hairstyle_clean.jpg",top_length:"2 inches",sides:"skin fade",texture:"smooth",products:"pomade"},trending:{name:"TRENDING",image:"https://stylelock-production.up.railway.app/static/hairstyle_trending.jpg",top_length:"4 inches",sides:"1 guard",texture:"wavy",products:"sea salt spray"}};
    function showScreen(id){document.querySelectorAll(".screen").forEach(s=>s.classList.remove("active"));document.getElementById("screen-"+id).classList.add("active");if(id==="loading"){const p=document.getElementById("progress-fill");p.style.animation="none";p.offsetHeight;p.style.animation="loadProgress 4s ease-out forwards";}}
    async function handlePayment(){try{const r=await fetch("/api/create-order",{method:"POST"});const d=await r.json();if(d.demo){showScreen("upload");return;}new Razorpay({key:d.key_id,amount:d.amount,currency:d.currency,name:"StyleLock",order_id:d.order_id,handler:()=>showScreen("upload"),theme:{color:"#c8e64a"}}).open();}catch(e){showScreen("upload");}}
    function handleImage(e){const f=e.target.files[0];if(!f)return;const r=new FileReader();r.onload=ev=>{document.getElementById("upload-preview").src=ev.target.result;document.getElementById("upload-preview-container").classList.add("visible");setTimeout(()=>{showScreen("loading");processImage();},800);};r.readAsDataURL(f);}
    async function processImage(){await new Promise(r=>setTimeout(r,4000));currentLooks=[HERO_LOOKS.bold,HERO_LOOKS.clean,HERO_LOOKS.trending];renderResults();showScreen("results");}
    function renderResults(){const s=document.getElementById("results-swiper");s.innerHTML=currentLooks.map((l,i)=>`<div class="result-slide"><div class="result-card"><div class="result-card-hero"><img src="${l.image}"><div class="result-look-name">${l.name}</div></div><div class="result-card-info"><div class="result-specs"><div class="result-spec"><div class="result-spec-label">TOP</div><div class="result-spec-value">${l.top_length}</div></div><div class="result-spec"><div class="result-spec-label">SIDES</div><div class="result-spec-value">${l.sides}</div></div><div class="result-spec"><div class="result-spec-label">TEXTURE</div><div class="result-spec-value">${l.texture}</div></div><div class="result-spec"><div class="result-spec-label">PRODUCTS</div><div class="result-spec-value">${l.products}</div></div></div><button class="result-next-btn" onclick="selectLook(${i})">SELECT THIS LOOK</button></div></div></div>`).join("");document.getElementById("results-dots").innerHTML=currentLooks.map((_,i)=>`<div class="dot ${i===0?"active":""}" data-index="${i}"></div>`).join("");s.addEventListener("scroll",()=>{const idx=Math.round(s.scrollLeft/s.offsetWidth);document.querySelectorAll(".dot").forEach((d,i)=>d.classList.toggle("active",i===idx));});}
    function selectLook(i){selectedLook=currentLooks[i];renderCutCard();showScreen("cutcard");}
    function renderCutCard(){const t=new Date().toLocaleDateString("en-IN",{day:"2-digit",month:"short",year:"numeric"});document.getElementById("cutcard-content").innerHTML=`<div class="cutcard-header"><div class="cutcard-logo">STYLELOCK</div><div class="cutcard-date">${t}</div></div><div class="cutcard-look-name">${selectedLook.name}</div><div class="cutcard-specs"><div class="cutcard-spec"><div class="cutcard-spec-label">TOP</div><div class="cutcard-spec-value">${selectedLook.top_length}</div></div><div class="cutcard-spec"><div class="cutcard-spec-label">SIDES</div><div class="cutcard-spec-value">${selectedLook.sides}</div></div><div class="cutcard-spec"><div class="cutcard-spec-label">TEXTURE</div><div class="cutcard-spec-value">${selectedLook.texture}</div></div><div class="cutcard-spec"><div class="cutcard-spec-label">PRODUCTS</div><div class="cutcard-spec-value">${selectedLook.products}</div></div></div><button class="cutcard-barber-btn" onclick="showScreen('barber');renderBarberMode();">BARBER MODE</button>`;}
    function renderBarberMode(){document.getElementById("barber-content").innerHTML=`<div class="barber-image-container"><img src="${selectedLook.image}"></div><div class="barber-specs-grid"><div class="barber-spec-card"><div class="barber-spec-label">TOP</div><div class="barber-spec-value">${selectedLook.top_length}</div></div><div class="barber-spec-card"><div class="barber-spec-label">SIDES</div><div class="barber-spec-value">${selectedLook.sides}</div></div><div class="barber-spec-card"><div class="barber-spec-label">TEXTURE</div><div class="barber-spec-value">${selectedLook.texture}</div></div><div class="barber-spec-card"><div class="barber-spec-label">PRODUCTS</div><div class="barber-spec-value">${selectedLook.products}</div></div></div><div class="barber-footer"><span class="barber-logo-text">STYLELOCK</span></div>`;}
    document.getElementById("home-unlock-btn").addEventListener("click",handlePayment);
    document.getElementById("upload-frame-btn").addEventListener("click",()=>document.getElementById("camera-input").click());
    document.getElementById("upload-take-btn").addEventListener("click",()=>document.getElementById("camera-input").click());
    document.getElementById("camera-input").addEventListener("change",handleImage);
    document.getElementById("barber-close").addEventListener("click",()=>showScreen("cutcard"));
  </script>
</body>
</html>"""

@app.get("/app", response_class=HTMLResponse)
async def serve_app():
    return FRONTEND_HTML

if __name__ == "__main__":
    import uvicorn
    uvicorn.run(app, host="0.0.0.0", port=int(os.getenv("PORT", 8000)))
